static ast_node_t *make_leaf(token_type_t type, const char *val) {
  token_t tok{};
  tok.type = type;
  tok.value = val;
  tok.length = (val != nullptr) ? std::strlen(val) : 0;
  return create_leaf_node(&tok);
}

static ast_node_t *chain_nodes(std::initializer_list<ast_node_t *> nodes) {
  ast_node_t *head = nullptr;
  ast_node_t *tail = nullptr;
  for (ast_node_t *node : nodes) {
    if (node == nullptr)
      continue;
    if (head == nullptr) {
      head = node;
      tail = node;
    } else {
      tail->next = node;
      tail = node;
    }
  }
  return head;
}

