// Helper to chain freshly allocated data_type_node_t* nodes for union/lambda
// types
static data_type_node_t *
chain_types(std::initializer_list<data_type_node_t *> types) {
  data_type_node_t *head = nullptr;
  data_type_node_t *tail = nullptr;
  for (data_type_node_t *t : types) {
    if (t == nullptr)
      continue;
    if (head == nullptr) {
      head = t;
      tail = t;
    } else {
      tail->next = t;
      tail = t;
    }
  }
  return head;
}

